<script lang="ts">
  import { onMount } from 'svelte';
  import Button from '$lib/components/ui/button/button.svelte';
  import { tr } from '../preferences.svelte';
  import { post,message,type Request } from './types';
  let {request,beforeMaintenance,active=true}:{request:Request;beforeMaintenance?:()=>boolean|Promise<boolean>;active?:boolean}=$props();
  let data=$state<any>(null),busy=$state(false),failure=$state(''),notice=$state(''),confirmInstall=$state(false),diagnostics=$state<any>(null),restarting=$state(false),expectedVersion='';
  let mounted=true;
  const installing=$derived(restarting||['preparing','installing','restarting'].includes(data?.installation?.status));
  async function load(){try{data=await request('/api/updates');}catch(error){failure=message(error);}}
  async function mutate(route:string,value:any){if(busy||installing)return;busy=true;failure='';notice='';try{const result=await post(request,route,value);if(route.endsWith('/install')){expectedVersion=value.version;restarting=true;notice=tr('Installation acceptée. Attente de reconnexion ; aucun nouvel envoi automatique.','Installation accepted. Waiting to reconnect; no automatic resubmission.');}else data=result;await load();}catch(error){failure=message(error);await load();notice=tr('État serveur relu. Aucun nouvel envoi automatique.','Server state refreshed. No automatic resubmission.');}finally{busy=false;}}
  async function install(){confirmInstall=false;try{if(beforeMaintenance&&!(await beforeMaintenance()))return;await mutate('/api/updates/install',{version:data.candidate.version,confirm:true});}catch(error){failure=message(error);}}
  async function diagnostic(){busy=true;failure='';try{diagnostics=await request('/api/diagnostics');}catch(error){failure=message(error);}finally{busy=false;}}
  function downloadDiagnostic(){const url=URL.createObjectURL(new Blob([JSON.stringify(diagnostics,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='diagnostic-compagnon.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  onMount(()=>{mounted=true;void load();const timer=setInterval(async()=>{if(!active||document.hidden||busy)return;if(restarting){try{const ping=await request('/api/ping');if(mounted&&ping.version===expectedVersion){restarting=false;notice=tr('Nouvelle version disponible. Tu peux recharger la page après avoir vérifié tes brouillons.','The new version is available. Reload the page after checking your drafts.');await load();}}catch{}}else await load();},4000);return()=>{mounted=false;clearInterval(timer);};});
</script>
<h2>{tr('Mises à jour et diagnostic','Updates and diagnostics')}</h2><p class="settings-description">{tr('Choisis ton canal de mise à jour et consulte les vérifications du compagnon. Une installation demande toujours une confirmation explicite.','Choose your update channel and inspect companion diagnostics. Installation always requires explicit confirmation.')}</p>
{#if data}<dl class="settings-dl"><dt>{tr('Version installée','Installed version')}</dt><dd>{data.currentVersion} · {data.installedChannel||'stable'}</dd><dt>{tr('Dernière vérification','Last check')}</dt><dd>{data.lastCheckedAt?new Date(data.lastCheckedAt).toLocaleString():tr('Jamais','Never')}</dd></dl>
<label class="setting-field">{tr('Canal de mise à jour','Update channel')}<select value={data.channel||'stable'} onchange={event=>mutate('/api/updates/preferences',{channel:event.currentTarget.value})} disabled={busy||installing}><option value="stable">Stable</option><option value="beta">{tr('Bêta','Beta')}</option></select></label><p class="settings-description">{data.channel==='beta'?tr('Le canal bêta propose aussi des versions de préparation.','The beta channel also offers prerelease versions.'):tr('Le canal stable propose les versions publiées comme stables.','The stable channel offers releases published as stable.')}</p><label class="setting-check"><input type="checkbox" checked={data.enabled!==false} onchange={event=>mutate('/api/updates/preferences',{enabled:event.currentTarget.checked})} disabled={busy||installing} />{tr('Vérifier automatiquement les mises à jour','Check for updates automatically')}</label>
<Button variant="outline" onclick={()=>mutate('/api/updates/check',{})} disabled={busy||installing||data.checking}>{tr('Rechercher une mise à jour','Check for updates')}</Button>
{#if data.candidate}<h3>{tr('Version proposée','Available version')} · {data.candidate.version}</h3><p class="settings-description">{data.candidate.publishedAt?new Date(data.candidate.publishedAt).toLocaleString():''}</p><pre>{data.candidate.notes||tr('Aucune note de version.','No release notes.')}</pre>{#if data.unavailableReason}<p class="settings-feedback">{data.unavailableReason}</p>{/if}<div class="settings-actions"><Button onclick={()=>confirmInstall=true} disabled={busy||installing||!data.canInstall||data.ignoredVersion===data.candidate.version}>{tr('Installer cette version','Install this version')}</Button><Button variant="ghost" onclick={()=>mutate('/api/updates/ignore',{version:data.candidate.version})} disabled={busy||installing}>{tr('Ignorer cette version','Ignore this version')}</Button></div>{:else}<p class="settings-feedback">{tr('Aucune nouvelle version proposée.','No new version available.')}</p>{/if}
{#if installing}<p class="settings-feedback" role="status">{data.installation?.message||notice||tr('Installation en cours…','Installing…')}</p>{/if}{#if data.error}<p class="settings-error">{typeof data.error==='string'?data.error:data.error.message}</p>{/if}
{/if}
{#if confirmInstall}<div class="confirm-action"><h3>{tr('Installer','Install')} {data.candidate.version} ?</h3><p class="settings-description">{tr('Le compagnon va redémarrer. Vérifie les fichiers non enregistrés et les brouillons avant de poursuivre.','The companion will restart. Check unsaved files and drafts before continuing.')}</p><div class="settings-actions"><Button onclick={install}>{tr('Confirmer l’installation','Confirm installation')}</Button><Button variant="ghost" onclick={()=>confirmInstall=false}>{tr('Annuler','Cancel')}</Button></div></div>{/if}
<div class="settings-divider"></div><h3>{tr('Diagnostic','Diagnostics')}</h3><p class="settings-description">{tr('Les vérifications peuvent contacter les services configurés, sans lancer de génération.','Checks may contact configured services without starting generation.')}</p><Button variant="outline" onclick={diagnostic} disabled={busy}>{tr('Lancer le diagnostic','Run diagnostics')}</Button>
{#if diagnostics}<pre aria-label={tr('Résultats du diagnostic','Diagnostic results')}>{JSON.stringify(diagnostics,null,2)}</pre><Button variant="ghost" onclick={downloadDiagnostic}>{tr('Télécharger le diagnostic','Download diagnostics')}</Button>{/if}
{#if failure}<p class="settings-error" role="alert">{failure}</p>{/if}{#if notice&&!installing}<p class="settings-feedback" role="status">{notice}</p>{/if}
